## `ErrorBoundary.tsx`

```tsx
import { Component, type ErrorInfo, type ReactNode } from 'react';

type FallbackProps = {
  error: Error;
  errorInfo: ErrorInfo | null;
  retry: () => void;
};

type Props = {
  children: ReactNode;
  /** Custom fallback UI. Falls back to a built-in panel if omitted. */
  fallback?: (props: FallbackProps) => ReactNode;
  /** Side-effect hook for your logging/monitoring service. */
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
  /** Called after the user clicks Retry. */
  onReset?: () => void;
  /** When any of these values change, the boundary auto-resets. */
  resetKeys?: unknown[];
};

type State = {
  error: Error | null;
  errorInfo: ErrorInfo | null;
};

const initialState: State = { error: null, errorInfo: null };

export class ErrorBoundary extends Component<Props, State> {
  state: State = initialState;

  // Render phase: only update state, no side effects here.
  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  // Commit phase: safe place for logging.
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    this.setState({ errorInfo });

    // Structured log — component stack is the part stack traces don't give you.
    console.error('[ErrorBoundary] Render error caught', {
      message: error.message,
      stack: error.stack,
      componentStack: errorInfo.componentStack,
    });

    // Never let the reporter itself crash the boundary.
    try {
      this.props.onError?.(error, errorInfo);
    } catch (reportingError) {
      console.error('[ErrorBoundary] onError handler threw', reportingError);
    }
  }

  componentDidUpdate(prevProps: Props): void {
    const { resetKeys } = this.props;
    if (!this.state.error || !resetKeys) return;

    const prevKeys = prevProps.resetKeys ?? [];
    const changed =
      prevKeys.length !== resetKeys.length ||
      resetKeys.some((key, i) => !Object.is(key, prevKeys[i]));

    if (changed) this.reset();
  }

  private reset = (): void => {
    this.setState(initialState);
  };

  private handleRetry = (): void => {
    this.props.onReset?.();
    this.reset();
  };

  render(): ReactNode {
    const { error, errorInfo } = this.state;
    if (!error) return this.props.children;

    if (this.props.fallback) {
      return this.props.fallback({ error, errorInfo, retry: this.handleRetry });
    }

    return (
      <div role="alert" className="error-boundary">
        <h2>Something went wrong</h2>
        <p>{error.message || 'An unexpected error occurred.'}</p>

        {process.env.NODE_ENV !== 'production' && errorInfo && (
          <details style={{ whiteSpace: 'pre-wrap' }}>
            <summary>Error details</summary>
            {error.stack}
            {errorInfo.componentStack}
          </details>
        )}

        <button type="button" onClick={this.handleRetry}>
          Retry
        </button>
      </div>
    );
  }
}
```

## Usage

```tsx
<ErrorBoundary
  resetKeys={[userId]}                       // auto-recover when route/data changes
  onError={(error, info) =>
    Sentry.captureException(error, {
      contexts: { react: { componentStack: info.componentStack } },
    })
  }
  onReset={() => queryClient.resetQueries()} // clear cached failures before remount
>
  <Dashboard userId={userId} />
</ErrorBoundary>
```

With a custom fallback:

```tsx
<ErrorBoundary
  fallback={({ error, retry }) => (
    <EmptyState title="Couldn't load the dashboard" description={error.message}>
      <Button onClick={retry}>Try again</Button>
    </EmptyState>
  )}
>
  <Dashboard />
</ErrorBoundary>
```

## Design notes worth knowing

- **Must be a class.** There is still no hook equivalent for `getDerivedStateFromError` / `componentDidCatch`. Libraries like `react-error-boundary` wrap the same class.
- **Two lifecycles, two jobs.** `getDerivedStateFromError` runs during render and must stay pure (React may call it twice in StrictMode); logging belongs in `componentDidCatch`.
- **Retry = remount.** Clearing state re-renders `children`. If the underlying cause (bad prop, poisoned cache) hasn't changed, it will immediately re-throw — that's why `onReset` exists, to clear the bad state first.
- **What it does *not* catch:** event handlers, `setTimeout`/promise callbacks, SSR, and errors thrown inside the boundary itself. Use `try/catch` for those, or a `window.onunhandledrejection` listener that routes into the same logger.
- **Placement matters.** One boundary at the app root gives you a whole-page blank state. Prefer several at meaningful seams (per route, per widget) so one broken panel doesn't take down the shell.

